import{_ as a,o as e,c as d,a as o}from"./chunks/framework.Ld7uezS_.js";const u=JSON.parse('{"title":"顶部栏目与左侧侧边栏对应关系审查","description":"","frontmatter":{},"headers":[],"relativePath":"outputs/navigation-audit-2026-08-21.md","filePath":"outputs/navigation-audit-2026-08-21.md","lastUpdated":1787296090000}'),r={name:"outputs/navigation-audit-2026-08-21.md"};function i(l,t,n,h,c,s){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="顶部栏目与左侧侧边栏对应关系审查" tabindex="-1">顶部栏目与左侧侧边栏对应关系审查 <a class="header-anchor" href="#顶部栏目与左侧侧边栏对应关系审查" aria-label="Permalink to &quot;顶部栏目与左侧侧边栏对应关系审查&quot;">​</a></h1><blockquote><p>审查日期：2026-08-21 审查方式：静态读取 VitePress 导航配置、首页学习路径和主要课程页链接；未启动开发服务器，未进行浏览器点击。 结论性质：本报告只定位导航结构与点击体验问题，不修改站点代码。</p></blockquote><h2 id="一、结论摘要" tabindex="-1">一、结论摘要 <a class="header-anchor" href="#一、结论摘要" aria-label="Permalink to &quot;一、结论摘要&quot;">​</a></h2><p>你的感觉是对的：目前不是单个链接失效，而是<strong>顶部导航、首页侧边栏、理论/技能页侧边栏使用了三套不同粒度的信息架构</strong>。链接大多能到达有效页面，但用户从顶部栏目进入后，左侧导航会切换成另一套上下文，导致“栏目名称—落地页—左侧菜单”之间不完全对应。</p><p>最明显的问题有三个：</p><ol><li><strong>顶部栏目是入口级，左侧菜单是内容级，但两者没有形成明确的父子关系</strong>。例如“理论考试”直接落到第 1 章，而左侧菜单显示十章；“技能操作”直接落到“设施监控”，但站点主线实际是“操作 → 保养 → 维修 → 检测”。</li><li><strong>进入理论页或技能页后，左侧侧边栏会完全替换首页/训练总览菜单</strong>。这意味着用户在课程页中看不到“零基础导学、技能路线图、只读训练、综合学习课”等上层入口，只能依赖顶部导航或浏览器返回。</li><li><strong>顶部栏目没有覆盖侧边栏中的关键学习入口</strong>。<code>核心术语表</code>、<code>技能考核路线图</code>、<code>综合学习课</code>、<code>权威依据与版本边界</code>、<code>标准逐条映射</code>都只在首页侧边栏出现；用户从理论/技能页进入时，这些入口的可见性和位置会变化。</li></ol><h2 id="二、当前结构" tabindex="-1">二、当前结构 <a class="header-anchor" href="#二、当前结构" aria-label="Permalink to &quot;二、当前结构&quot;">​</a></h2><h3 id="顶部导航" tabindex="-1">顶部导航 <a class="header-anchor" href="#顶部导航" aria-label="Permalink to &quot;顶部导航&quot;">​</a></h3><table tabindex="0"><thead><tr><th>显示文本</th><th>当前目标</th><th>实际含义</th></tr></thead><tbody><tr><td>首页</td><td><code>/</code></td><td>站点首页</td></tr><tr><td>考核说明</td><td><code>/exam-guide</code></td><td>考试信息说明</td></tr><tr><td>零基础导学</td><td><code>/beginner-guide</code></td><td>学习路线与前置概念</td></tr><tr><td>只读训练</td><td><code>/training</code></td><td>训练总览</td></tr><tr><td>理论考试</td><td><code>/theory/01-professional-ethics</code></td><td>理论十章中的第 1 章</td></tr><tr><td>技能操作</td><td><code>/skill/01-monitoring</code></td><td>技能五项中的第 1 项“设施监控”</td></tr></tbody></table><h3 id="路径下的左侧菜单" tabindex="-1"><code>/</code> 路径下的左侧菜单 <a class="header-anchor" href="#路径下的左侧菜单" aria-label="Permalink to &quot;`/` 路径下的左侧菜单&quot;">​</a></h3><ol><li>开始学习：首页、考核说明、零基础导学、核心术语表、来源、技能路线图、综合学习课、标准映射</li><li>只读训练：训练总览、理论训练、技能训练、题源说明</li><li>理论考试：十章理论</li><li>技能操作考核：五项职业功能 + 三类设备项目卡</li></ol><h3 id="theory-路径下的左侧菜单" tabindex="-1"><code>/theory/</code> 路径下的左侧菜单 <a class="header-anchor" href="#theory-路径下的左侧菜单" aria-label="Permalink to &quot;`/theory/` 路径下的左侧菜单&quot;">​</a></h3><p>只保留“理论考试 · 知识点”及十章理论，不再显示首页、学习路线和训练入口。</p><h3 id="skill-路径下的左侧菜单" tabindex="-1"><code>/skill/</code> 路径下的左侧菜单 <a class="header-anchor" href="#skill-路径下的左侧菜单" aria-label="Permalink to &quot;`/skill/` 路径下的左侧菜单&quot;">​</a></h3><p>只保留“技能操作考核 · 职业功能”及五项职业功能、三类设备项目卡，不再显示首页、学习路线和训练入口。</p><h2 id="三、可复现的-点起来奇怪-路径" tabindex="-1">三、可复现的“点起来奇怪”路径 <a class="header-anchor" href="#三、可复现的-点起来奇怪-路径" aria-label="Permalink to &quot;三、可复现的“点起来奇怪”路径&quot;">​</a></h2><h3 id="路径-a-顶部-理论考试-与落地页不匹配" tabindex="-1">路径 A：顶部“理论考试”与落地页不匹配 <a class="header-anchor" href="#路径-a-顶部-理论考试-与落地页不匹配" aria-label="Permalink to &quot;路径 A：顶部“理论考试”与落地页不匹配&quot;">​</a></h3><p><code>首页 → 顶部“理论考试” → 职业道德</code></p><p>用户通常会把“理论考试”理解为一个总览或理论入口页，但实际直接进入第 1 章；左侧标题变成“理论考试 · 知识点”，看起来像已经进入章节内部。若用户想先看理论学习说明或训练入口，需要再依赖其他菜单。</p><p><strong>问题级别：P1（信息架构误导）</strong></p><h3 id="路径-b-顶部-技能操作-把用户带到非主线起点" tabindex="-1">路径 B：顶部“技能操作”把用户带到非主线起点 <a class="header-anchor" href="#路径-b-顶部-技能操作-把用户带到非主线起点" aria-label="Permalink to &quot;路径 B：顶部“技能操作”把用户带到非主线起点&quot;">​</a></h3><p><code>首页 → 顶部“技能操作” → 设施监控</code></p><p>当前用户目标是“检测维修保养”。站点正文明确把设施监控定位为基础，主线是“设施操作、设施保养、设施维修、设施检测”。但顶部“技能操作”却直接把用户落到“设施监控”，容易让用户误以为监控是当前报考方向的首要/完整入口；同时左侧菜单还把五项职业功能和设备项目卡平铺在一起。</p><p><strong>问题级别：P1（学习主线误导）</strong></p><h3 id="路径-c-从理论页无法直接看到训练与学习路线" tabindex="-1">路径 C：从理论页无法直接看到训练与学习路线 <a class="header-anchor" href="#路径-c-从理论页无法直接看到训练与学习路线" aria-label="Permalink to &quot;路径 C：从理论页无法直接看到训练与学习路线&quot;">​</a></h3><p><code>首页 → 顶部“理论考试” → 第 1 章 → 查看左侧菜单</code></p><p>进入理论页后，首页侧边栏中的“只读训练”“技能考核路线图”“综合学习课”“核心术语表”等全部消失。用户若想从某章跳到训练，必须回到顶部“只读训练”或返回首页。</p><p><strong>问题级别：P1（上下文断裂）</strong></p><h3 id="路径-d-从技能页无法回到同一套课程入口" tabindex="-1">路径 D：从技能页无法回到同一套课程入口 <a class="header-anchor" href="#路径-d-从技能页无法回到同一套课程入口" aria-label="Permalink to &quot;路径 D：从技能页无法回到同一套课程入口&quot;">​</a></h3><p><code>首页 → 顶部“技能操作” → 设施监控 → 查看左侧菜单</code></p><p>进入技能页后，用户只能看到技能五项和设备项目卡；“技能路线图”本身不在当前侧边栏，“只读训练”也不在当前侧边栏。正文中的路线说明与左侧菜单被拆开，学习者会感到需要来回找入口。</p><p><strong>问题级别：P1（上下文断裂）</strong></p><h3 id="路径-e-顶部与侧边栏的粒度不一致" tabindex="-1">路径 E：顶部与侧边栏的粒度不一致 <a class="header-anchor" href="#路径-e-顶部与侧边栏的粒度不一致" aria-label="Permalink to &quot;路径 E：顶部与侧边栏的粒度不一致&quot;">​</a></h3><p>顶部把“理论考试”和“技能操作”当作两个并列栏目；侧边栏却把理论十章、技能五项、设备项目卡、训练和治理页面混合组织。顶部没有“核心术语表”“综合学习课”等同级入口，用户无法从顶部判断这些页面属于哪个栏目。</p><p><strong>问题级别：P2（层级与命名不一致）</strong></p><h2 id="四、最小改造建议" tabindex="-1">四、最小改造建议 <a class="header-anchor" href="#四、最小改造建议" aria-label="Permalink to &quot;四、最小改造建议&quot;">​</a></h2><p>建议不要先改内容页，而是先统一导航模型：</p><h3 id="方案-1-保留当前页面文件-调整入口指向-推荐-改动最小" tabindex="-1">方案 1：保留当前页面文件，调整入口指向（推荐，改动最小） <a class="header-anchor" href="#方案-1-保留当前页面文件-调整入口指向-推荐-改动最小" aria-label="Permalink to &quot;方案 1：保留当前页面文件，调整入口指向（推荐，改动最小）&quot;">​</a></h3><ol><li>把顶部“理论考试”改成一个明确的理论总览入口；若暂不新增页面，可先指向 <code>/training-theory</code>，或在 <code>/theory/01-professional-ethics</code> 前增加理论入口页。</li><li>把顶部“技能操作”改名为“技能考核”或“技能路线”，指向 <code>/skill-roadmap</code>；不要直接指向“设施监控”。</li><li>顶部增加“课程路线”或“学习路线”，统一指向 <code>/beginner-guide</code>；将当前“零基础导学”保留为清晰入口。</li><li>顶部增加一个“训练”下拉菜单，包含训练总览、理论训练、技能训练；不要让训练只靠首页侧边栏可见。</li><li>在理论和技能侧边栏顶部增加一个稳定的“学习导航”组，至少保留：首页、零基础导学、技能路线图、训练总览、术语表。这样进入深层页面后不会完全丢失上层上下文。</li></ol><h3 id="方案-2-按-课程—理论—技能—训练-重构-后续优化" tabindex="-1">方案 2：按“课程—理论—技能—训练”重构（后续优化） <a class="header-anchor" href="#方案-2-按-课程—理论—技能—训练-重构-后续优化" aria-label="Permalink to &quot;方案 2：按“课程—理论—技能—训练”重构（后续优化）&quot;">​</a></h3><p>将信息架构固定为四个一级栏目：</p><ul><li><strong>开始学习</strong>：首页、考核说明、零基础导学、术语表、来源</li><li><strong>理论课程</strong>：理论总览、十章理论</li><li><strong>技能课程</strong>：技能路线图、四项主线、三类设备项目卡</li><li><strong>只读训练</strong>：训练总览、理论训练、技能训练、题源说明</li></ul><p><code>标准逐条映射</code>可放到“来源/课程治理”中，不作为普通学习者的主导航入口。</p><h2 id="五、建议的优先级" tabindex="-1">五、建议的优先级 <a class="header-anchor" href="#五、建议的优先级" aria-label="Permalink to &quot;五、建议的优先级&quot;">​</a></h2><table tabindex="0"><thead><tr><th>优先级</th><th>修正项</th><th>原因</th></tr></thead><tbody><tr><td>P0</td><td>顶部“技能操作”改为指向技能路线图，并修正显示名</td><td>直接影响当前报考方向的第一步选择</td></tr><tr><td>P1</td><td>理论/技能侧边栏保留稳定的上层学习导航</td><td>解决进入深层页面后导航上下文消失</td></tr><tr><td>P1</td><td>为理论和技能增加明确的总览入口</td><td>避免顶部栏目直接落到第 1 个子章节</td></tr><tr><td>P2</td><td>统一顶部与侧边栏的栏目命名和粒度</td><td>消除“顶部是栏目、侧边栏是混合目录”的认知负担</td></tr><tr><td>P2</td><td>将标准映射从普通学习菜单降级为参考/治理入口</td><td>减少零基础用户看到审计型页面后的干扰</td></tr></tbody></table><h2 id="六、审查边界" tabindex="-1">六、审查边界 <a class="header-anchor" href="#六、审查边界" aria-label="Permalink to &quot;六、审查边界&quot;">​</a></h2><p>本轮确认的是导航配置和静态链接关系，不等于浏览器渲染后的视觉审查。未启动 VitePress 开发服务器，也未修改配置。下一步如果你确认方向，建议先按 P0/P1 做一次最小导航改造，再由用户本地打开站点确认实际视觉和点击手感。</p>',47)])])}const b=a(r,[["render",i]]);export{u as __pageData,b as default};
